{"implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    node_to_idx = {name: i for i, name in enumerate(nodes)}
    edges = []
    for a, b, d in distances:
        i = node_to_idx[a]
        j = node_to_idx[b]
        if i > j:
            i, j = j, i
            a, b = b, a
        mut = max(core[a], core[b], d)
        edges.append((mut, i, j, a, b))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = list(range(n))
    rank = [0] * n
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total = 0.0
    for mut, i, j, a, b in edges:
        if union(i, j):
            mst_edges.append([a, b, mut])
            total += mut
            if len(mst_edges) == n - 1:
                break
    return {'edges': mst_edges, 'total_weight': total}"}
